// Server-side readers for the published evidence (copied into src/generated by scripts/sync-data.mjs).
// Nothing here computes a number: every value comes from a file that `uv run verify` recomputes.
import "server-only";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const GEN = join(process.cwd(), "src", "generated");

function read<T = any>(rel: string): T | null {
  const p = join(GEN, rel);
  return existsSync(p) ? (JSON.parse(readFileSync(p, "utf8")) as T) : null;
}

function list(rel: string): string[] {
  const p = join(GEN, rel);
  return existsSync(p) ? readdirSync(p) : [];
}

export const EXCHANGES = ["binance", "okx", "bybit", "bitget", "kucoin", "coindcx", "wazirx"] as const;
export type ExchangeId = (typeof EXCHANGES)[number];
export const INDIAN: ExchangeId[] = ["coindcx", "wazirx"];

export type Floor = { asset: string; floor: number; provers: number; reserve: number | null };
export type HeartbeatState = "normal" | "below_usual_pattern" | "not_enough_data" | "halt_confirmed" | "unknown";

export function devnet(): any {
  return read("data/devnet.json") ?? {};
}

export function reservesSummary(): Record<string, any> {
  return read("evidence/reserves/summary.json") ?? {};
}

export function reserves(id: ExchangeId): any | null {
  return read(`evidence/reserves/${id}.json`);
}

export function score(id: ExchangeId): any | null {
  return read(`evidence/score/${id}.json`);
}

export function heartbeat(id: ExchangeId): any | null {
  return read(`evidence/heartbeat/${id}.json`);
}

export function onchainReports(): Record<string, any> {
  return read("evidence/onchain/reports.json") ?? {};
}

export function proofs(id?: ExchangeId): any[] {
  return list("evidence/proofs")
    .filter((f) => f.endsWith(".json"))
    .map((f) => read(`evidence/proofs/${f}`))
    .filter((p) => p && (!id || p.exchange === id));
}

export function backtest(event: string): any | null {
  return read(`evidence/backtests/${event}.json`);
}

export function coverBacktest(event: string): any | null {
  return read(`evidence/backtests/cover-${event}.json`);
}

export function events(): any[] {
  return read<any>("data/events.json")?.events ?? [];
}

export function replays(): any[] {
  return list("evidence/onchain")
    .filter((f) => f.startsWith("replay-") && f.endsWith(".json"))
    .map((f) => read(`evidence/onchain/${f}`));
}

export function inclusionVectors(): any | null {
  return read("evidence/inclusion/testvectors.json");
}

export function binanceRoots(): any[] {
  return read<any>("data/binance-roots.json")?.roots ?? [];
}

export function registry(id: ExchangeId): any | null {
  return read(`data/registry/${id}.json`);
}

export function scoreParams(): any {
  return read("data/score-params.json");
}

/** One row for the board, all fields straight from evidence files ("—" + reason when missing). */
export function boardRow(id: ExchangeId) {
  const s = score(id);
  const r = reservesSummary()[id] ?? {};
  const hb = heartbeat(id);
  const floors: Floor[] = s?.inputs?.floors ?? [];
  return {
    id,
    name: r.name ?? s?.inputs?.name ?? id,
    reservesUsd: r.total_usd ?? null,
    reservesReason: r.reason ?? null,
    reservesAsOf: r.as_of ?? null,
    topAssets: r.top ?? [],
    floors,
    provers: s?.inputs?.provers ?? 0,
    heartbeatState: (hb?.state ?? s?.inputs?.heartbeat_state ?? "unknown") as HeartbeatState,
    heartbeatAsOf: hb?.as_of ?? null,
    heartbeat24h: hb?.last_24h_by_chain ?? null,
    heartbeatReason: s?.sources?.heartbeat?.reason ?? null,
    score: s?.score ?? null,
    deductions: s?.deductions ?? [],
    indian: INDIAN.includes(id),
  };
}

export const EXPLORER = (kind: "tx" | "address", v: string) => `https://explorer.solana.com/${kind}/${v}?cluster=devnet`;

/** The PASS/FAIL lines from the last `uv run verify` (evidence/verify.json). */
export function verifyResult(): { passed: number; total: number; lines: { ok: boolean; msg: string }[] } | null {
  return read("evidence/verify.json");
}

function csv(rel: string): string[][] {
  const p = join(GEN, rel);
  if (!existsSync(p)) return [];
  return readFileSync(p, "utf8").trim().split(/\r?\n/).slice(1).map((l) => l.split(","));
}

export type GridCell = { t: string; count: number; median: number; ratio: number | null };

/**
 * FTX hot-wallet withdrawals (Ethereum), one cell per hour for the 28 days before 11 Nov 2022, each compared with the
 * median of the same hour over the previous 28 days (the same baseline the heartbeat rule uses). From data/raw/ftx-2022-11/hourly.csv.
 */
export function ftxGrid() {
  const rows = csv("data/raw/ftx-2022-11/hourly.csv");
  const counts = new Map(rows.map(([t, c]) => [t, Number(c)]));
  const H = 3600_000;
  const end = Date.parse("2022-11-11T00:00:00Z");
  const start = end - 28 * 24 * H;
  const at = (ms: number) => counts.get(new Date(ms).toISOString().replace(".000Z", "Z")) ?? 0;
  const days: { day: string; cells: GridCell[] }[] = [];
  for (let d = 0; d < 28; d++) {
    const dayStart = start + d * 24 * H;
    const cells: GridCell[] = [];
    for (let h = 0; h < 24; h++) {
      const ms = dayStart + h * H;
      const past = Array.from({ length: 28 }, (_, k) => at(ms - (k + 1) * 24 * H)).sort((a, b) => a - b);
      const median = (past[13] + past[14]) / 2;
      const count = at(ms);
      cells.push({ t: new Date(ms).toISOString(), count, median, ratio: median >= 4 ? count / median : null });
    }
    days.push({ day: new Date(dayStart).toISOString().slice(0, 10), cells });
  }
  const bt = backtest("ftx-2022-11")?.result;
  const meta = read<{ rows: number }>("data/raw/ftx-2022-11/meta.json");
  return { days, firstAlarm: bt?.first_alarm ?? null, T: bt?.T ?? null, K: bt?.K ?? 0.25, leadHours: bt?.first_alarm_minus_T_hours ?? null, transfers: meta?.rows ?? null };
}

/** Last `hours` of observed outflows (all chains summed) for a live exchange, from data/live/<id>/hourly.csv. */
export function liveHourly(id: ExchangeId, hours = 72): { t: string; n: number }[] {
  const rows = csv(`data/live/${id}/hourly.csv`);
  return rows.slice(-hours).map(([t, ...n]) => ({ t, n: n.reduce((a, b) => a + Number(b || 0), 0) }));
}
